    12→	"github.com/OffchainLabs/prysm/v6/network/authorization"
    13→	gethRPC "github.com/ethereum/go-ethereum/rpc"
    14→	log "github.com/sirupsen/logrus"
    15→	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
    16→)
    17→
    18→// Endpoint is an endpoint with authorization data.
    19→type Endpoint struct {
    20→	Url  string
    21→	Auth AuthorizationData
    22→}
    23→
    24→// AuthorizationData holds all information necessary to authorize with HTTP.
    25→type AuthorizationData struct {
    26→	Method authorization.Method
    27→	Value  string
    28→	JwtId  string
    29→}
    30→
    31→// Equals compares two endpoints for equality.
    32→func (e Endpoint) Equals(other Endpoint) bool {
    33→	return e.Url == other.Url && e.Auth.Equals(other.Auth)
    34→}
    35→
    36→// HttpClient creates a http client object dependent
    37→// on the properties of the network endpoint.
    38→func (e Endpoint) HttpClient() *http.Client {
    39→	if e.Auth.Method != authorization.Bearer {
    40→		return &http.Client{Transport: otelhttp.NewTransport(http.DefaultTransport)}
    41→	}
    42→	return NewHttpClientWithSecret(e.Auth.Value, e.Auth.JwtId)
    43→}
    44→
    45→// Equals compares two authorization data objects for equality.
    46→func (d *AuthorizationData) Equals(other AuthorizationData) bool {
    47→	return d.Method == other.Method && d.Value == other.Value
    48→}
    49→
    50→// ToHeaderValue retrieves the value of the authorization header from AuthorizationData.
    51→func (d *AuthorizationData) ToHeaderValue() (string, error) {
    52→	switch d.Method {
    53→	case authorization.Basic:
    54→		return "Basic " + d.Value, nil
    55→	case authorization.Bearer:
    56→		return "Bearer " + d.Value, nil
    57→	case authorization.None:
    58→		return "", nil
    59→	}
    60→
    61→	return "", errors.New("could not create HTTP header for unknown authorization method")
    62→}
    63→
    64→// HttpEndpoint extracts an httputils.Endpoint from the provider parameter.
    65→func HttpEndpoint(eth1Provider string) Endpoint {
    66→	endpoint := Endpoint{
    67→		Url: "",
    68→		Auth: AuthorizationData{
    69→			Method: authorization.None,
    70→			Value:  "",
    71→		}}
    72→
    73→	authValues := strings.Split(eth1Provider, ",")
    74→	endpoint.Url = strings.TrimSpace(authValues[0])
    75→	if len(authValues) > 2 {
    76→		log.Errorf(
    77→			"ETH1 endpoint string can contain one comma for specifying the authorization header to access the provider."+
    78→				" String contains too many commas: %d. Skipping authorization.", len(authValues)-1)
    79→	} else if len(authValues) == 2 {
    80→		switch Method(strings.TrimSpace(authValues[1])) {
    81→		case authorization.Basic:
    82→			basicAuthValues := strings.Split(strings.TrimSpace(authValues[1]), " ")
    83→			if len(basicAuthValues) != 2 {
    84→				log.Errorf("Basic Authentication has incorrect format. Skipping authorization.")
    85→			} else {
    86→				endpoint.Auth.Method = authorization.Basic
    87→				endpoint.Auth.Value = base64.StdEncoding.EncodeToString([]byte(basicAuthValues[1]))
    88→			}
    89→		case authorization.Bearer:
    90→			bearerAuthValues := strings.Split(strings.TrimSpace(authValues[1]), " ")
    91→			if len(bearerAuthValues) != 2 {
    92→				log.Errorf("Bearer Authentication has incorrect format. Skipping authorization.")
    93→			} else {
    94→				endpoint.Auth.Method = authorization.Bearer
    95→				endpoint.Auth.Value = bearerAuthValues[1]
    96→			}
    97→		case authorization.None:
    98→			log.Errorf("Authorization has incorrect format or authorization type is not supported.")
    99→		}
   100→	}
   101→	return endpoint
   102→}
   103→
   104→// Method returns the authorizationmethod.AuthorizationMethod corresponding with the parameter value.
   105→func Method(auth string) authorization.Method {
   106→	if strings.HasPrefix(strings.ToLower(auth), "basic") {
   107→		return authorization.Basic
   108→	}
   109→	if strings.HasPrefix(strings.ToLower(auth), "bearer") {
   110→		return authorization.Bearer
   111→	}
   112→	return authorization.None
   113→}
   114→
   115→// NewHttpClientWithSecret returns a http client that utilizes
   116→// jwt authentication.
   117→func NewHttpClientWithSecret(secret, id string) *http.Client {
   118→	authTransport := &jwtTransport{
   119→		underlyingTransport: http.DefaultTransport,
   120→		jwtSecret:           []byte(secret),
   121→		jwtId:               id,
   122→	}
   123→	return &http.Client{
   124→		Timeout:   DefaultRPCHTTPTimeout,
   125→		Transport: otelhttp.NewTransport(authTransport),
   126→	}
   127→}
   128→
   129→func NewExecutionRPCClient(ctx context.Context, endpoint Endpoint, headers http.Header) (*gethRPC.Client, error) {
   130→	// Need to handle ipc and http
   131→	var client *gethRPC.Client
   132→	u, err := url.Parse(endpoint.Url)
   133→	if err != nil {
   134→		return nil, err
   135→	}
   136→	switch u.Scheme {
   137→	case "http", "https":
   138→		client, err = gethRPC.DialOptions(ctx, endpoint.Url, gethRPC.WithHTTPClient(endpoint.HttpClient()), gethRPC.WithHeaders(headers))
   139→		if err != nil {
   140→			return nil, err
   141→		}
   142→	case "", "ipc":
   143→		client, err = gethRPC.DialIPC(ctx, endpoint.Url)
   144→		if err != nil {
   145→			return nil, err
   146→		}
   147→	default:
   148→		return nil, fmt.Errorf("no known transport for URL scheme %q", u.Scheme)
   149→	}
   150→	return client, nil
   151→}
