   222→func ValidatorPerformanceResponseFromConsensus(e *eth.ValidatorPerformanceResponse) *ValidatorPerformanceResponse {
   223→	inclusionSlots := make([]uint64, len(e.InclusionSlots))
   224→	for i, index := range e.InclusionSlots {
   225→		inclusionSlots[i] = uint64(index)
   226→	}
   227→	inclusionDistances := make([]uint64, len(e.InclusionDistances))
   228→	for i, index := range e.InclusionDistances {
   229→		inclusionDistances[i] = uint64(index)
   230→	}
   231→	missingValidators := make([]string, len(e.MissingValidators))
   232→	for i, key := range e.MissingValidators {
   233→		missingValidators[i] = hexutil.Encode(key)
   234→	}
   235→	publicKeys := make([]string, len(e.PublicKeys))
   236→	for i, key := range e.PublicKeys {
   237→		publicKeys[i] = hexutil.Encode(key)
   238→	}
   239→	if len(e.CurrentEffectiveBalances) == 0 {
   240→		e.CurrentEffectiveBalances = make([]uint64, 0)
   241→	}
   242→	if len(e.BalancesBeforeEpochTransition) == 0 {
   243→		e.BalancesBeforeEpochTransition = make([]uint64, 0)
   244→	}
   245→	if len(e.BalancesAfterEpochTransition) == 0 {
   246→		e.BalancesAfterEpochTransition = make([]uint64, 0)
   247→	}
   248→	if len(e.CorrectlyVotedSource) == 0 {
   249→		e.CorrectlyVotedSource = make([]bool, 0)
   250→	}
   251→	if len(e.CorrectlyVotedTarget) == 0 {
   252→		e.CorrectlyVotedTarget = make([]bool, 0)
   253→	}
   254→	if len(e.CorrectlyVotedHead) == 0 {
   255→		e.CorrectlyVotedHead = make([]bool, 0)
   256→	}
   257→	if len(e.InactivityScores) == 0 {
   258→		e.InactivityScores = make([]uint64, 0)
   259→	}
   260→	return &ValidatorPerformanceResponse{
   261→		CurrentEffectiveBalances:      e.CurrentEffectiveBalances,
   262→		InclusionSlots:                inclusionSlots,
   263→		InclusionDistances:            inclusionDistances,
   264→		CorrectlyVotedSource:          e.CorrectlyVotedSource,
   265→		CorrectlyVotedTarget:          e.CorrectlyVotedTarget,
   266→		CorrectlyVotedHead:            e.CorrectlyVotedHead,
   267→		BalancesBeforeEpochTransition: e.BalancesBeforeEpochTransition,
   268→		BalancesAfterEpochTransition:  e.BalancesAfterEpochTransition,
   269→		MissingValidators:             missingValidators,
   270→		AverageActiveValidatorBalance: e.AverageActiveValidatorBalance,
   271→		PublicKeys:                    publicKeys,
   272→		InactivityScores:              e.InactivityScores,
   273→	}
   274→}
