   374→func ChainHeadResponseFromConsensus(e *eth.ChainHead) *ChainHead {
   375→	return &ChainHead{
   376→		HeadSlot:                   fmt.Sprintf("%d", e.HeadSlot),
   377→		HeadEpoch:                  fmt.Sprintf("%d", e.HeadEpoch),
   378→		HeadBlockRoot:              hexutil.Encode(e.HeadBlockRoot),
   379→		FinalizedSlot:              fmt.Sprintf("%d", e.FinalizedSlot),
   380→		FinalizedEpoch:             fmt.Sprintf("%d", e.FinalizedEpoch),
   381→		FinalizedBlockRoot:         hexutil.Encode(e.FinalizedBlockRoot),
   382→		JustifiedSlot:              fmt.Sprintf("%d", e.JustifiedSlot),
   383→		JustifiedEpoch:             fmt.Sprintf("%d", e.JustifiedEpoch),
   384→		JustifiedBlockRoot:         hexutil.Encode(e.JustifiedBlockRoot),
   385→		PreviousJustifiedSlot:      fmt.Sprintf("%d", e.PreviousJustifiedSlot),
   386→		PreviousJustifiedEpoch:     fmt.Sprintf("%d", e.PreviousJustifiedEpoch),
   387→		PreviousJustifiedBlockRoot: hexutil.Encode(e.PreviousJustifiedBlockRoot),
   388→		OptimisticStatus:           e.OptimisticStatus,
   389→	}
   390→}
   391→
   392→func (m *ChainHead) ToConsensus() (*eth.ChainHead, error) {
   393→	headSlot, err := strconv.ParseUint(m.HeadSlot, 10, 64)
   394→	if err != nil {
   395→		return nil, server.NewDecodeError(err, "HeadSlot")
   396→	}
   397→	headEpoch, err := strconv.ParseUint(m.HeadEpoch, 10, 64)
   398→	if err != nil {
   399→		return nil, server.NewDecodeError(err, "HeadEpoch")
   400→	}
   401→	headBlockRoot, err := bytesutil.DecodeHexWithLength(m.HeadBlockRoot, fieldparams.RootLength)
   402→	if err != nil {
   403→		return nil, server.NewDecodeError(err, "HeadBlockRoot")
   404→	}
   405→	finalizedSlot, err := strconv.ParseUint(m.FinalizedSlot, 10, 64)
