    19→
    20→// Copy sends out a copy of the current header info.
    21→func (h *HeaderInfo) Copy() *HeaderInfo {
    22→	return &HeaderInfo{
    23→		Hash:   bytesutil.ToBytes32(h.Hash[:]),
    24→		Number: new(big.Int).Set(h.Number),
    25→		Time:   h.Time,
    26→	}
    27→}
    28→
    29→// MarshalJSON marshals as JSON.
    30→func (h *HeaderInfo) MarshalJSON() ([]byte, error) {
    31→	type HeaderInfoJson struct {
    32→		Number *hexutil.Big   `json:"number"`
    33→		Hash   common.Hash    `json:"hash"`
    34→		Time   hexutil.Uint64 `json:"timestamp"`
    35→	}
    36→	var enc HeaderInfoJson
    37→
    38→	enc.Number = (*hexutil.Big)(h.Number)
    39→	enc.Hash = h.Hash
    40→	enc.Time = hexutil.Uint64(h.Time)
    41→	return json.Marshal(enc)
    42→}
    43→
    44→// UnmarshalJSON unmarshals from JSON.
    45→func (h *HeaderInfo) UnmarshalJSON(data []byte) error {
    46→	type HeaderInfoJson struct {
    47→		Number *hexutil.Big    `json:"number"`
    48→		Hash   *common.Hash    `json:"hash"`
    49→		Time   *hexutil.Uint64 `json:"timestamp"`
    50→	}
    51→	var dec HeaderInfoJson
    52→	if err := json.Unmarshal(data, &dec); err != nil {
    53→		return err
    54→	}
    55→	if dec.Time == nil {
    56→		return errors.New("missing required field 'timestamp'")
    57→	}
    58→	h.Time = uint64(*dec.Time)
    59→	if dec.Number == nil {
    60→		return errors.New("missing required field 'number'")
    61→	}
    62→	h.Number = (*big.Int)(dec.Number)
    63→	if dec.Hash == nil {
    64→		return errors.New("missing required field 'hash'")
    65→	}
    66→	h.Hash = *dec.Hash
    67→	return nil
    68→}
